def solve(grid):
    """
    Envelope rule:
    - Vertical span from row (first_8 - 1) to (last_8_cluster_start - 1)
    - When 2's column is within [min_gap, max_gap], some rows get FULL fill
    - Rows from first_8 upward get horizontal fills
    - After final cluster start, use min_gap as anchor
    """
    h, w = len(grid), len(grid[0])
    result = [row[:] for row in grid]

    # Find 2
    two_pos = None
    for r in range(h):
        if two_pos: break
        for c in range(w):
            if grid[r][c] == 2:
                two_pos = (r, c)
                break

    if not two_pos:
        return result
    two_col = two_pos[1]

    # Find 8-rows and their gaps
    rows8 = [r for r in range(h) if any(grid[r][c] == 8 for c in range(w))]
    row_gaps = {}
    for r in rows8:
        gaps = []
        has_8_before = False
        for c in range(w):
            if grid[r][c] == 8:
                has_8_before = True
            elif has_8_before and grid[r][c] == 0:
                after_has_8 = any(grid[r][cc] == 8 for cc in range(c + 1, w))
                if after_has_8:
                    gaps.append(c)
        row_gaps[r] = tuple(gaps)

    if not row_gaps:
        return result

    # All gaps span
    all_gaps = sorted(set(c for gaps in row_gaps.values() for c in gaps))
    span_min, span_max = all_gaps[0], all_gaps[-1]

    # Envelope bounds
    first_8 = rows8[0]
    top = first_8 - 1
    if top < 0: top = 0

    # Find cluster start (first row of last consecutive group)
    i = len(rows8) - 1
    while i > 0 and rows8[i] - rows8[i-1] == 1:
        i -= 1
    cluster_start = rows8[i]
    bottom = cluster_start - 1
    bottom = min(bottom, h - 1)

    print(f"Envelope: {top}-{bottom}, span: [{span_min}, {span_max}], two_col: {two_col}")
    print(f"Two_col in span: {span_min <= two_col <= span_max}")

    # Draw envelope
    for r in range(top, bottom + 1):
        r_offset = r - first_8

        if r_offset == 0:
            # Row 1: Above first 8-row, horizontal from first 8's gaps
            if row_gaps[first_8]:
                gmin, gmax = min(row_gaps[first_8]), max(row_gaps[first_8])
                for c in range(gmin, gmax + 1):
                    if result[r][c] != 8:
                        result[r][c] = 2
        elif r_offset == 1:
            # Row 2: First 8-row itself, draw at gap columns
            if r in row_gaps and row_gaps[r]:
                for c in row_gaps[r]:
                    if result[r][c] == 0:
                        result[r][c] = 2
        elif r_offset == 2:
            # Row 3: Below first 8-row. 
            # If two_col is in span, horizontal fill. Else just vertical at first gap.
            if span_min <= two_col <= span_max:
                # Fill from 0 to w-1? No, let me check
                pass
            # Actually in demo, row_offset=2 (row 3) has fill from span_min to span_max
            gmin, gmax = min(row_gaps[first_8]), max(row_gaps[first_8])
            for c in range(gmin, gmax + 1):
                if result[r][c] == 0:
                    result[r][c] = 2

    return result

