    # Get gap columns for each 8-row
    def get_gaps(r):
        gaps = []
        for c in range(w):
            if grid[r][c] == 0:
                has_left = any(grid[r][lc] == 8 for lc in range(c))
                has_right = any(grid[r][rc] == 8 for rc in range(c+1, w))
                if has_left and has_right:
                    gaps.append(c)
        return tuple(sorted(gaps))

    row_gaps = {r: get_gaps(r) for r in rows8}

    first_8 = rows8[0]
    last_8 = rows8[-1]

    # Find last cluster (consecutive 8-rows at end)
    i = len(rows8) - 2
    while i >= 0 and rows8[i+1] - rows8[i] == 1:
        i -= 1
    cluster_start = rows8[i + 1]

    # Envelope bounds
    top = first_8 - 1
    bottom = cluster_start - 1
    top = max(0, top)
    bottom = min(bottom, h - 1)

    # Build the zones: each non-8 row belongs to a zone defined by adjacent 8-rows
    # Zone 0: rows before first 8 (just row top=first_8-1)
    # Zone 1: rows between first_8 and second_8 (or after first_8 in consecutive)
    # etc.

    # Process each row
    for r in range(top, bottom + 1):
        offset = r - first_8

        if r in row_gaps:
            # 8-row: draw gaps vertically
            for c in row_gaps[r]:
                if result[r][c] != 8:
                    result[r][c] = 2
        else:
            # Gap row - determine fill pattern
            if offset == -1:
                # Before first 8: horizontal fill from first 8's gaps
                for c in row_gaps[first_8]:
                    if result[r][c] != 8:
                        result[r][c] = 2
            else:
                # Between or after 8s
                # Find which 8-row this gap row is "paired" with
                # Row just after 8-row i belongs to zone starting at i
                # Count consecutive gaps after each 8

                # Find which 8-row this follows
                prev_8 = None
                for row_8 in rows8:
                    if row_8 + 1 == r:
                        prev_8 = row_8
                        break

                if prev_8 is not None:
                    # This is immediately after an 8-row
                    # Count how many gaps there are before next 8
                    next_8 = None
                    for row_8 in rows8:
                        if row_8 > prev_8:
                            next_8 = row_8
                            break

                    if next_8 is not None:
                        # How many gap rows before next_8?
                        gap_rows_between = next_8 - prev_8 - 1
                        # This gap row is at offset = r - first_8
                        gap_offset = r - prev_8

                        if gap_offset == 0:
                            # First gap row after 8: horizontal fill from prev_8's gaps
                            for c in row_gaps[prev_8]:
                                if result[r][c] != 8:
                                    result[r][c] = 2
                        elif gap_offset == 1 and gap_rows_between == 2:
                            # Second gap row in a double-gap zone: FULL fill
                            for c in range(w):
                                if result[r][c] == 0:
                                    result[r][c] = 2
                        elif gap_offset > 1:
                            # Third and later gap row: vertical from prev_8's gaps
                            for c in row_gaps[prev_8]:
