                                result[r, :] = 2
                            else:
                                for c in gaps1:
                                    result[r, c] = 2
                        else:
                            for c in gaps1:
                                result[r, c] = 2
                else:
                    # No dist-2: combine all gaps and fill
                    all_gaps = set()
                    for idx in dist1:
                        all_gaps.update(get_gap_columns(rows_8[idx]))
                    if all_gaps:
                        min_c, max_c = min(all_gaps), max(all_gaps)
                        result[r, min_c:max_c+1] = 2

    for r in rows_8:
        gaps = get_gap_columns(r)
        if gaps:
            for c in gaps:
                result[r, c] = 2

    return result

result = solve(demo_input)
for r in range(len(result)):
    match = (result[r] == expected[r]).all()
    print(f"Row {r}: {'OK' if match else 'FAIL'}")
